/* Drift check for collation-tables.ts (GENERATED by
 * scripts/gen-wasm-collation-tables.mjs from ICU 78.3's FractionalUCA.txt and
 * Unicode 17's UnicodeData.txt). The inputs are not vendored (3.6 MB of
 * text for a 93 KB table): the generator pins their URLs and sha256
 * digests and reads them from ~/.cache/tsinter-dl/cldr-48-uca (or
 * TSINTER_COLLATION_SOURCES). Where they are present this re-renders the
 * table and requires the checked-in file byte for byte; where they are
 * not, it says so and checks only what needs no inputs. The tables' MEANING
 * is held to Node by wasm-collation.test.ts either way. */
import { readFileSync } from "node:fs";
import { describe, expect, test } from "vitest";
// @ts-expect-error — plain .mjs script, no type declarations
import { DEFAULT_SOURCE_DIR, OUT_PATH, build, render, sourcesPresent } from "../../../scripts/gen-wasm-collation-tables.mjs";

const dir: string = process.env["TSINTER_COLLATION_SOURCES"] ?? DEFAULT_SOURCE_DIR;

describe("collation-tables.ts drift check", () => {
  test.skipIf(!sourcesPresent(dir))(`re-rendering from the pinned inputs (${dir}) gives the checked-in file`, () => {
    const fresh = render(build(dir)) as string;
    expect(fresh === readFileSync(OUT_PATH, "utf8")).toBe(true);
  }, 120_000);

  test("the checked-in file says where it came from", () => {
    const text = readFileSync(OUT_PATH, "utf8");
    expect(text).toContain("GENERATED by scripts/gen-wasm-collation-tables.mjs");
    expect(text).toContain("ICU 78.3");
  });
});
